/**
 * Lead changes are a separate permission from a general project edit.
 * `leadId: null` clears the lead. Any other lead must be an active member of
 * this organization who would be allowed to `project:update` the project.
 */
export async function changeProjectLead(
  actor: Actor,
  input: ChangeProjectLeadInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:change_lead", projectResource(project));
  assertNotArchived("Project", project.id, project);

  if (input.leadId !== null) {
    const member = requireFound(
      await memberRepo.findMember(input.orgId, input.leadId),
      "Member",
      input.leadId,
    );
    if (member.status !== "active") {
      throw new NotFoundError("Member", input.leadId);
    }
    assertCan(
      { userId: member.userId, orgId: input.orgId, role: member.role },
      "project:update",
      projectResource(project),
    );
  }

  return projectRepo.updateProject({
    orgId: input.orgId,
    projectId: input.projectId,
    leadId: input.leadId,
  });
}","tool_output_for_prompt":"The file /private/tmp/bench-scratch/1de931e9-dccb-4c84-b031-8cc7e0d553e4/src/server/services/project-service.ts has been updated successfully.","tool_output_for_prompt_concise":"The file /private/tmp/bench-scratch/1de931e9-dccb-4c84-b031-8cc7e0d553e4/src/server/services/project-service.ts has been updated.","absolute_path":"/private/tmp/bench-scratch/1de931e9-dccb-4c84-b031-8cc7e0d553e4/src/server/services/project-service.ts","edits":{"details":[{"old_string":"  assertCan(actor, "project:update", projectResource(project));
