/**
 * Temporary verification for changeProjectLead. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { ROLE_MATRIX, can } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { changeProjectLeadSchema } from "@/schemas/project";
import { getDb, members } from "@/server/db";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { NotFoundError } from "@/server/services/_support";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberService from "@/server/services/member-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import { makeActor, ALICE, ORG_A } from "../helpers/factories";
import type { ProjectId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("changeProjectLead", () => {
  it("schema requires leadId and accepts null", () => {
    const orgId = "01HZZZAAAAAAAAAAAAAAAAAAAA";
    const projectId = "01HZZZPPPPPPPPPPPPPPPPPPPP";
    expect(
      changeProjectLeadSchema.safeParse({ orgId, projectId }).success,
    ).toBe(false);
    expect(
      changeProjectLeadSchema.parse({ orgId, projectId, leadId: null }).leadId,
    ).toBeNull();
    expect(
      changeProjectLeadSchema.safeParse({ orgId, projectId, leadId: "nope" }).success,
    ).toBe(false);
  });

  it("role table is admin, and the current lead escalates", () => {
    expect(ROLE_MATRIX["project:change_lead"]).toBe("admin");
    const project = {
      kind: "project" as const,
      orgId: ORG_A,
      projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
      visibility: "org" as const,
      leadId: ALICE,
    };
    const other = { ...project, leadId: null };
    expect(can(makeActor({ role: "owner" }), "project:change_lead", other)).toBe(true);
    expect(can(makeActor({ role: "admin" }), "project:change_lead", other)).toBe(true);
    expect(can(makeActor({ role: "member" }), "project:change_lead", other)).toBe(false);
    expect(can(makeActor({ role: "viewer" }), "project:change_lead", other)).toBe(false);
    expect(can(makeActor({ role: "viewer", userId: ALICE }), "project:change_lead", project)).toBe(
      true,
    );
    expect(can(makeActor({ role: "member", userId: ALICE }), "project:change_lead", project)).toBe(
      true,
    );
    expect(can(makeActor({ role: "viewer" }), "project:change_lead", project)).toBe(false);
  });

  it("transfers, clears, and rejects the documented cases", async () => {
    const tenant = await createTenant("leadchange", "growth");
    const other = await createTenant("leadother", "growth");
    const originalLead = tenant.project.leadId;

    const transferred = await projectService.changeProjectLead(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.member,
    });
    expect(transferred.leadId).toBe(tenant.userIds.member);

    const cleared = await projectService.changeProjectLead(tenant.actors.owner, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: null,
    });
    expect(cleared.leadId).toBeNull();

    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.viewer,
    });

    const handedOff = await projectService.changeProjectLead(tenant.actors.viewer, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      leadId: tenant.userIds.member,
    });
    expect(handedOff.leadId).toBe(tenant.userIds.member);

    await expect(
      projectService.changeProjectLead(tenant.actors.member, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const still = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(still?.leadId).toBe(tenant.userIds.member);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: other.org.id,
        projectId: tenant.project.id,
        leadId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: other.project.id,
        leadId: tenant.userIds.admin,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stranger = await userRepo.insertUser({
      email: "stranger@leadchange.test",
      name: "Stranger",
      passwordHash: "seed",
    });
    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: stranger.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: other.userIds.owner,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    expect(viewerMember).not.toBeNull();
    await memberService.removeMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: viewerMember!.id,
    });
    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const outsider = await userRepo.insertUser({
      email: "suspended@leadchange.test",
      name: "Suspended",
      passwordHash: "seed",
    });
    const suspended = await memberRepo.insertMember(
      tenant.org.id,
      outsider.id,
      "admin",
      null,
    );
    getDb()
      .update(members)
      .set({ status: "suspended" })
      .where(eq(members.id, suspended.id))
      .run();
    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: outsider.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.userIds.viewer,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.changeProjectLead(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: tenant.actors.viewer.userId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const freshViewer = await userRepo.insertUser({
      email: "viewer2@leadchange.test",
      name: "Viewer Two",
      passwordHash: "seed",
    });
    await memberRepo.insertMember(tenant.org.id, freshViewer.id, "viewer", null);
    await expect(
